package com.cloudticket.order.client;
import java.util.Map; import org.springframework.beans.factory.annotation.Value; import org.springframework.core.ParameterizedTypeReference; import org.springframework.stereotype.Component;
@Component public class PromotionClient { private static final ParameterizedTypeReference<Map<String,Object>> RESPONSE=new ParameterizedTypeReference<>(){}; private final InternalServiceClient internal; private final String baseUrl; public PromotionClient(InternalServiceClient i,@Value("${cloudticket.promotion-base-url:http://promotion-service:8084}") String base){internal=i;baseUrl=base;}
 public Quote quote(String orderId,String userId,String activityId,String sessionId,int original,String couponId){if(couponId==null||couponId.isBlank())return new Quote(null,0,original);Map<String,Object> b=internal.postForBody(baseUrl,"/api/internal/promotions/quote",Map.of("orderId",orderId,"userId",userId,"activityId",activityId,"sessionId",sessionId,"originalAmountMinor",original,"couponId",couponId),RESPONSE);return new Quote(String.valueOf(b.getOrDefault("reservationId","")),((Number)b.getOrDefault("discountAmountMinor",0)).intValue(),((Number)b.getOrDefault("payableAmountMinor",original)).intValue());}
 public void consume(String reservationId){transition(reservationId,"consume");} public void release(String reservationId){transition(reservationId,"release");} public void restore(String reservationId){transition(reservationId,"restore");} private void transition(String id,String action){if(id!=null&&!id.isBlank())internal.post(baseUrl,"/api/internal/promotions/{id}/{action}",Map.of(),id,action);} public record Quote(String reservationId,int discountAmountMinor,int payableAmountMinor){}
}
